TERMS=[terminal('profile-required','Исполнение не подтверждено. Обозначения аппаратов раннего профиля нельзя переносить на другой вариант электровоза; используйте только общий безопасный triage.','variant_mismatch'),terminal('reassess','Причина локализована до безопасного уровня. Дальнейшие ремонтные/переключательные действия — только по действующему источнику и подтверждённому профилю.','reassess'),terminal('not-this-scenario','Признак не соответствует этому маршруту. Вернитесь к выбору симптома.','route_back')]

def addref(s,r):
    a=s.setdefault('sourceRefs',[]); a[:]=[x for x in a if x.get('sourceId')!=r['sourceId']]; a.append(deepcopy(r))

def build(sid,cfg,old_causes):
    start,scope,anchors,extra,related,pneu=cfg
    nodes=[
      q('start',start,[('Да','profile-check'),('Нет','not-this-scenario')]),
      q('profile-check','Подтверждено раннее базовое исполнение, для которого применимы указанные аппараты и цепи?',[('Да','scope'),('Нет / не уверен','profile-required')]),
      q('scope',f'Отказ действительно ограничен областью «{scope}», а не является более общим отказом питания/управления?',[('Да','command'),('Нет, отказ шире','scope-finding'),('Не определено','scope-unknown')]),
      finding('scope-finding','Сначала локализуйте общий источник питания/управления; профильный аппарат этого маршрута может быть вторичным признаком.'),
      info('scope-unknown','Сравните другие секции/группы и доступные функции до выбора аппарата.','command'),
      q('command','Штатная команда/разрешение на функцию подтверждены, но фактический результат или обратная связь отсутствуют?',[('Да','anchor'),('Нет, команды/разрешения нет','command-finding'),('Не определено','command-unknown')]),
      finding('command-finding','При отсутствии команды/разрешения причина находится до исполнительного аппарата; не воздействуйте на него вручную.'),
      info('command-unknown','Сначала отделите потерю команды от отказа исполнительной цепи.','anchor'),
      q('anchor',f'Для подтверждённого раннего профиля схема связывает отказ с {anchors}; это подтверждается штатной индикацией/фактическим состоянием без пробных переключений?',[('Да','evidence'),('Нет','anchor-finding'),('Не уверен','anchor-unknown')]),
      finding('anchor-finding',f'{anchors} не подтверждены как причина. Не использовать старое восстановительное действие как диагностический тест.'),
      info('anchor-unknown',f'{anchors} остаются только профильной гипотезой до проверки схемы и фактического исполнения.','evidence'),
      q('evidence','Есть независимое подтверждение причины по последовательности события, штатной индикации и физическому эффекту без повторного воспроизведения отказа?',[('Да','reassess'),('Нет','reassess'),('Не могу подтвердить','reassess')]),
      *TERMS]
    causes=[]
    for c in old_causes+[extra,'Отказ обратной связи/индикации при иной фактической причине','Несоответствие выбранного профиля фактическому исполнению']:
        if c not in causes: causes.append(c)
    checks=[
      {'title':'Область отказа','action':'Сравнить секции/группы и связанные функции без повторного воспроизведения отказа.','expected':'Понятно, общий отказ или локальный.','ifAbnormal':'При общем отказе перейти к маршруту питания/управления.','level':'CAB'},
      {'title':'Команда и физический эффект','action':'Сопоставить штатную команду, индикацию и фактическое состояние функции.','expected':'Отделена потеря команды от отказа исполнительного канала.','ifAbnormal':'Не воздействовать на аппарат вручную.','level':'CAB'},
      {'title':'Профильная цепь','action':f'Проверять {anchors} только по схеме подтверждённого исполнения и в рамках допуска.','expected':'Кандидат подтверждён схемой/измерением.','ifAbnormal':'Не выполнять пробные замены, повторные включения и обходы.','level':'AUTHORIZED_ONLY'}]
    prohibited=['Не выполнять повторные включения автоматов/защит или набор режима только для воспроизведения отказа.','Не включать контакторы, БВ, ГВ, QT1 и другие аппараты вручную и не подавать питание в обход штатного управления.','Не заменять предохранители/не восстанавливать тепловую защиту пробно как метод локализации.','Не назначать допустимый режим дальнейшего следования только по старой рекомендации 2010 года.']
    if pneu: prohibited.append('Не вмешиваться в пневмоаппаратуру под давлением и не создавать искусственную потребность в воздухе ради проверки.')
    return nodes,causes,checks,prohibited,related

def main():
    app=load(APP_ASSET); patch=load(PATCH_ASSET)
    if app!=patch: raise SystemExit('app/patch diagnostics differ before transform')
    out=deepcopy(app); by={s['id']:s for s in out['scenarios']}
    for sid,cfg in CFG.items():
        s=by[sid]
        old=[x.get('summary','') for x in s.get('possibleCauses',[]) if x.get('summary')]
        nodes,causes,checks,prohibited,related=build(sid,cfg,old)
        apply_route(s,nodes=nodes,immediate=['Зафиксировать первую индикацию, секцию/группу и физический эффект до любых восстановительных действий.','Подтвердить исполнение электровоза до использования обозначений раннего профиля.','Не воспроизводить КЗ/срабатывание защиты и не воздействовать на аппараты вручную ради диагностики.'],causes=causes,checks=checks,prohibited=prohibited,related=related)
        s['possibleCauses']=[{'summary':x} for x in causes]
        s['actions']=[{'summary':'Только безопасный triage по наблюдаемым признакам. Ремонт, ручное воздействие, обход защиты и пробные замены не являются диагностическими шагами этого маршрута.','sourceBound':True,'riskClass':'normal','userFacingPolicy':'TRIAGE_ONLY_NO_REPAIR'}]
        s['sourceAgeNote']='Повторный аудит 26.09.2026: №671р/2010 оставлен только как историческая симптомная сверка. №996/р и заводское РЭ используются с проверкой фактического исполнения; опасные старые действия не переносятся в пользовательский маршрут.'
        s['sourceAudit']={'auditedAt':V,'scope':'comprehensive_remaining95_batchA','status':'IMPROVE'}
        for r in s.setdefault('sourceRefs',[]):
            if r.get('sourceId')=='ER-SRC-010':
                r['role']='legacy_symptom_crosscheck_only'; r['sourceKind']='TRAINING'; r['version']={'label':'№671р от 31.03.2010','revision':'заменён №996/р; только историческая/симптомная сверка','verifiedAt':V,'status':'HISTORICAL'}
        addref(s,R996); addref(s,R1); addref(s,R4)
        if cfg[5]: addref(s,R6)
    dump(APP_ASSET,out); dump(PATCH_ASSET,out)
    if APP_ASSET.read_bytes()!=PATCH_ASSET.read_bytes(): raise SystemExit('app/patch diagnostics differ after transform')
    print('ERMAK_LEGACY_BATCHA_DEEPENED='+','.join(sorted(CFG)))

if __name__=='__main__': main()
